public class ConstructorFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(Class<?>[] paramTypes, Object[] args) {
        try {
            Object built = ConstructorFinder.build(EventTicket.class, paramTypes, args);
            if (built == null) {
                return "null";
            }
            return ((EventTicket) built).describe();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("every declared constructor arity", "[0, 1, 2, 3]",
                String.valueOf(ConstructorFinder.arities(EventTicket.class)));
        check("the no-argument constructor", "unknown#0@0.0",
                describe(new Class<?>[] {}, new Object[] {}));
        check("the one-argument constructor", "Gig#1@10.0",
                describe(new Class<?>[] { String.class }, new Object[] { "Gig" }));
        check("String plus primitive int", "Gig#7@25.0",
                describe(new Class<?>[] { String.class, int.class }, new Object[] { "Gig", 7 }));
        check("all three parameters", "Gig#7@99.5",
                describe(new Class<?>[] { String.class, int.class, double.class },
                        new Object[] { "Gig", 7, 99.5 }));
        check("Integer.class does not match an int parameter", "null",
                describe(new Class<?>[] { String.class, Integer.class }, new Object[] { "Gig", 7 }));
        check("a signature that does not exist at all", "null",
                describe(new Class<?>[] { int.class }, new Object[] { 3 }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

