import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// Provided -- do not edit.
class EventTicket {

    private final String event;
    private final int seat;
    private final double price;

    EventTicket() {
        this("unknown", 0, 0.0);
    }

    EventTicket(String event) {
        this(event, 1, 10.0);
    }

    EventTicket(String event, int seat) {
        this(event, seat, 25.0);
    }

    EventTicket(String event, int seat, double price) {
        this.event = event;
        this.seat = seat;
        this.price = price;
    }

    String describe() {
        return event + "#" + seat + "@" + price;
    }
}

public class ConstructorFinder {

    public static Object build(Class<?> type, Class<?>[] paramTypes, Object[] args) throws Exception {
        Constructor<?> constructor;
        try {
            constructor = type.getDeclaredConstructor(paramTypes);
        } catch (NoSuchMethodException e) {
            return null;
        }
        constructor.setAccessible(true);
        return constructor.newInstance(args);
    }

    public static List<Integer> arities(Class<?> type) {
        List<Integer> counts = new ArrayList<>();
        for (Constructor<?> constructor : type.getDeclaredConstructors()) {
            counts.add(constructor.getParameterCount());
        }
        Collections.sort(counts);
        return counts;
    }
}
